// Step 2: Validate Event Schema
const body = $input.first().json.body || $input.first().json;

const required = ['event_id', 'timestamp', 'username', 'event_type', 'source_ip'];
const missing = required.filter(f => !body[f]);

if (missing.length > 0) {
  return [{
    json: {
      error: true,
      message: `Malformed event payload. Missing required fields: ${missing.join(', ')}`,
      status_code: 400
    }
  }];
}

return [{
  json: {
    ...body,
    validated: true,
    ingested_at: new Date().toISOString()
  }
}];

// Step 3: Check Duplicate Event
const event = $input.first().json;

// Retrieve or initialize execution state memory
const staticData = $getWorkflowStaticData('global');
staticData.processedEventIds = staticData.processedEventIds || [];

if (staticData.processedEventIds.includes(event.event_id)) {
  return [{
    json: {
      is_duplicate: true,
      event_id: event.event_id,
      message: 'Duplicate event ID detected. Skipped redundant processing.'
    }
  }];
}

// Record ID to prevent duplicate processing
staticData.processedEventIds.push(event.event_id);
if (staticData.processedEventIds.length > 500) {
  staticData.processedEventIds.shift();
}

return [{
  json: {
    ...event,
    is_duplicate: false
  }
}];

// Step 4: Store Event in local memory / Google Sheets queue
const event = $input.first().json;
const staticData = $getWorkflowStaticData('global');
staticData.eventLog = staticData.eventLog || [];

staticData.eventLog.push(event);
if (staticData.eventLog.length > 200) {
  staticData.eventLog.shift();
}

return [{ json: event }];

// Step 5: Fetch Recent User Events within 30-minute correlation window
const currentEvent = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const eventLog = staticData.eventLog || [currentEvent];

const now = new Date(currentEvent.timestamp || new Date()).getTime();
const windowMs = 30 * 60 * 1000; // 30 minutes

const userEvents = eventLog.filter(e => 
  e.username === currentEvent.username &&
  (now - new Date(e.timestamp).getTime()) <= windowMs
);

return [{
  json: {
    current_event: currentEvent,
    correlated_events: userEvents.length > 0 ? userEvents : [currentEvent],
    user: currentEvent.username,
    event_count: userEvents.length || 1
  }
}];

// Step 6: Correlate Events and prepare prompt for Google Gemini
const data = $input.first().json;
const events = data.correlated_events;

const prompt = `You are the Rogue Protocol Autonomous AI Security Incident Response Agent.
Analyze the following simulated security events for user: ${data.user}.

Rules:
1. Analyze only the supplied simulated events. Do not invent missing facts.
2. Distinguish observed facts from assumptions.
3. Explain why events may be related temporally or operationally.
4. Assign severity based strictly on evidence (LOW, MEDIUM, HIGH, CRITICAL).
5. Recommend safe, simulated containment steps.
6. Do not claim certainty; use wording like "potential incident" and "requires investigation".
7. Return VALID JSON ONLY conforming to the required schema.

Events Observed:
${JSON.stringify(events, null, 2)}

Required JSON format:
{
  "incident_detected": boolean,
  "incident_type": string,
  "title": string,
  "severity": "LOW" | "MEDIUM" | "HIGH" | "CRITICAL",
  "confidence": number,
  "summary": string,
  "observed_facts": string[],
  "reasoning": string,
  "recommended_actions": [
    {
      "action": string,
      "risk": "low" | "medium" | "high",
      "requires_approval": boolean
    }
  ],
  "requires_human_review": boolean
}`;

return [{
  json: {
    ...data,
    analysis_prompt: prompt
  }
}];

// Step 8: Validate and Parse AI JSON
const item = $input.first().json;

try {
  let rawText = '';
  if (item.candidates && item.candidates[0]?.content?.parts[0]?.text) {
    rawText = item.candidates[0].content.parts[0].text;
  } else if (item.response) {
    rawText = item.response;
  }

  let parsed = {};
  if (rawText) {
    parsed = JSON.parse(rawText);
  } else {
    // Fallback deterministic analysis if Gemini key not set
    const types = (item.correlated_events || []).map(e => e.event_type);
    const isTakeover = types.includes('large_download') || (types.includes('password_changed') && types.includes('user_reported'));
    const isSuspicious = types.filter(t => t === 'login_failed').length >= 2;

    if (isTakeover) {
      parsed = {
        incident_detected: true,
        incident_type: 'possible_account_compromise',
        title: 'Possible Account Compromise & Bulk Exfiltration',
        severity: 'HIGH',
        confidence: 0.92,
        summary: 'Correlated brute-force, anomalous login, credential change, and mass download.',
        observed_facts: ['Consecutive failed logins', 'Foreign IP login', 'Password reset', 'Archive download'],
        reasoning: 'Temporal sequence indicates full account compromise pattern.',
        recommended_actions: [
          { action: 'Simulate temporary account suspension', risk: 'high', requires_approval: true },
          { action: 'Simulate edge firewall null-route for source IP', risk: 'medium', requires_approval: true },
          { action: 'Archive telemetry to forensic log', risk: 'low', requires_approval: false }
        ],
        requires_human_review: true
      };
    } else if (isSuspicious) {
      parsed = {
        incident_detected: true,
        incident_type: 'suspicious_login_activity',
        title: 'Suspicious Authentication Sequence',
        severity: 'MEDIUM',
        confidence: 0.82,
        summary: 'Repeated authentication failures followed by login from unexpected IP.',
        observed_facts: ['Repeated password rejections', 'Immediate subsequent success'],
        reasoning: 'Possible credential guessing attempt.',
        recommended_actions: [
          { action: 'Simulate step-up MFA challenge requirement', risk: 'medium', requires_approval: true },
          { action: 'Log behavioral baseline shift', risk: 'low', requires_approval: false }
        ],
        requires_human_review: false
      };
    } else {
      parsed = {
        incident_detected: false,
        summary: 'Routine legitimate activity.',
        severity: 'LOW',
        confidence: 0.99
      };
    }
  }

  return [{
    json: {
      ...item,
      ai_analysis: parsed,
      valid_ai_json: true
    }
  }];
} catch (e) {
  return [{
    json: {
      ...item,
      valid_ai_json: false,
      parse_error: e.message
    }
  }];
}

// Step 9: Apply Deterministic Safety Rules
const item = $input.first().json;
const analysis = item.ai_analysis;

// Rule 1: High & Critical ALWAYS require human review
if (analysis.severity === 'HIGH' || analysis.severity === 'CRITICAL') {
  analysis.requires_human_review = true;
}

// Rule 2: Any action altering access or credentials requires approval
if (analysis.recommended_actions) {
  analysis.recommended_actions = analysis.recommended_actions.map(act => {
    const sensitiveTerms = ['suspend', 'disable', 'block', 'revoke', 'freeze', 'restrict', 'reset', 'password'];
    const isSensitive = sensitiveTerms.some(term => act.action.toLowerCase().includes(term));
    return {
      ...act,
      requires_approval: act.requires_approval || isSensitive
    };
  });
}

return [{
  json: {
    ...item,
    ai_analysis: analysis,
    safety_rules_applied: true
  }
}];

// Step 11: Create or Update Incident
const item = $input.first().json;
const analysis = item.ai_analysis;
const user = item.user;
const correlated = item.correlated_events || [];

const incidentId = `INC-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`;

const incident = {
  incident_id: incidentId,
  title: analysis.title || 'Potential Security Incident',
  incident_type: analysis.incident_type || 'unclassified',
  severity: analysis.severity || 'MEDIUM',
  confidence: analysis.confidence || 0.85,
  status: 'ACTION_REQUIRED',
  affected_user: user,
  summary: analysis.summary,
  observed_facts: analysis.observed_facts || [],
  reasoning: analysis.reasoning || '',
  event_ids: correlated.map(e => e.event_id),
  recommended_actions: analysis.recommended_actions || [],
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString(),
  is_simulated: true
};

return [{
  json: {
    ...item,
    incident
  }
}];

// Step 12: Create Approval Requests for sensitive actions
const item = $input.first().json;
const incident = item.incident;

const approvals = (incident.recommended_actions || [])
  .filter(a => a.requires_approval)
  .map((a, idx) => ({
    approval_id: `APP-${Date.now()}-${idx + 1}`,
    incident_id: incident.incident_id,
    action: a.action,
    reason: `Containment action recommended for ${incident.severity} incident.`,
    impact: `Simulated containment for ${incident.affected_user}. Safe demo only.`,
    status: 'PENDING',
    requested_at: new Date().toISOString()
  }));

return [{
  json: {
    ...item,
    approvals
  }
}];

// Step 13: Send Alert / Honest Preview Fallback
const item = $input.first().json;
const incident = item.incident;

const notification = {
  recipient: 'soc-team@fictional-corp.internal',
  subject: `[${incident.severity} ALERT] Rogue Protocol: Potential Incident ${incident.incident_id}`,
  body: `Rogue Protocol AI Response Agent has detected a potential ${incident.severity} incident for ${incident.affected_user}.\n\nSummary: ${incident.summary}\n\nHuman authorization is required for simulated containment.`,
  timestamp: new Date().toISOString(),
  is_preview_fallback: true
};

return [{
  json: {
    ...item,
    notification
  }
}];

// Step 14: Write Audit Log
const item = $input.first().json;
const incident = item.incident;

const log = {
  log_id: `AUD-${Date.now()}`,
  timestamp: new Date().toISOString(),
  action_type: 'INCIDENT_CREATED',
  description: `n8n workflow created incident ${incident?.incident_id || 'N/A'} with severity ${incident?.severity || 'LOW'}`,
  operator: 'n8n Automation Pipeline',
  details: { incident_id: incident?.incident_id }
};

return [{
  json: {
    ...item,
    audit_log: log
  }
}];
